const $=s=>document.querySelector(s),KEY='forma.v1',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID(),today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},dateText=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'});
const foods=[{name:'Rolled oats',cal:389,p:17,c:66,f:7,icon:'🥣'},{name:'Greek yogurt',cal:73,p:10,c:4,f:2,icon:'🥛'},{name:'Banana',cal:89,p:1.1,c:23,f:.3,icon:'🍌'},{name:'Chicken breast, cooked',cal:165,p:31,c:0,f:3.6,icon:'🍗'},{name:'Rice, cooked',cal:130,p:2.7,c:28,f:.3,icon:'🍚'},{name:'Tofu',cal:144,p:17,c:3,f:9,icon:'🥢'},{name:'Egg, whole',cal:143,p:13,c:1,f:10,icon:'🥚'},{name:'Lentils, cooked',cal:116,p:9,c:20,f:.4,icon:'🫘'},{name:'Milk, 1.5% fat',cal:47,p:3.4,c:5,f:1.5,icon:'🥛'},{name:'Apple',cal:52,p:.3,c:14,f:.2,icon:'🍎'}];
const defaults=()=>({profile:{name:'',goal:'Build muscle',weight:'',height:'',target:'',experience:'Beginner',days:3,equipment:'Gym',diet:'No preference',limitations:'',cal:2200,protein:130,carbs:260,fat:70,onboarded:false},meals:[],weights:[],sessions:[],routines:[],folders:[],folderOpen:{},water:{},checkins:[],chat:[],active:null});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||defaults()}catch{state=defaults()}if(!state.trainingFoldersV1){state.routines=state.routines.filter(r=>!((r.id==='upper'&&r.exercises.every((e,i)=>e.sets===3&&e.reps===[10,12,10,12][i]&&e.kg===0)&&r.name==='Upper body foundations'&&r.exercises.map(e=>e.name).join('|')==='Bench press|Lat pulldown|Seated shoulder press|Cable row')||(r.id==='lower'&&r.exercises.every((e,i)=>e.sets===3&&e.reps===[8,10,12,15][i]&&e.kg===0)&&r.name==='Lower body foundations'&&r.exercises.map(e=>e.name).join('|')==='Squat|Romanian deadlift|Leg curl|Calf raise')));state.trainingFoldersV1=true;}state.folders=state.folders||[];state.folderOpen=state.folderOpen||{};
let catalogSelection=null;let pickerState={q:'',muscle:'',equipment:'',source:''};let routineRestDraft=[];let rhythmDate=today();let page='today',selectedDate=today(),mealMode='manual',editId=null,chartMetric='weight',timerEnd=0,timerInterval=null;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Storage is full or unavailable. Export your data before closing.')}}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}function closeModal(){$('#modal').close()}function modalHead(t){return `<div class="modal-head"><h2>${t}</h2><button class="close" aria-label="Close dialog" onclick="closeModal()">×</button></div>`}function sum(date=selectedDate){return state.meals.filter(m=>m.date===date).reduce((a,m)=>{['cal','p','c','f'].forEach(k=>a[k]+=Number(m[k])||0);return a},{cal:0,p:0,c:0,f:0})}const round=n=>Math.round(n),pct=(n,d)=>Math.min(100,Math.max(0,n/d*100));
const links=[['today','◫','Today'],['food','◉','Food diary'],['workouts','⌁','Training'],['progress','↗','Progress'],['coach','✧','AI coach'],['settings','⚙','Settings']];
function go(p){page=links.some(x=>x[0]===p)?p:'today';location.hash=page;render();window.scrollTo(0,0)}window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(p!==page)go(p)});
function render(){for(const target of ['#desktop-nav','#mobile-nav'])$(target).innerHTML=links.filter(x=>target!=='#mobile-nav'||x[0]!=='settings').map(([id,icon,t])=>`<button class="${page===id?'active':''}" onclick="go('${id}')"><span class="nav-icon">${icon}</span>${t}</button>`).join('');$('#crumb').textContent=links.find(x=>x[0]===page)?.[2];$('#side-name').textContent=state.profile.name||'Your profile';$('.avatar').textContent=(state.profile.name||'F')[0].toUpperCase();$('#app').innerHTML=({today:dashboard,food:foodPage,workouts:workoutPage,progress:progressPage,coach:coachPage,settings:settingsPage}[page])()}
function title(eyebrow,t,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${t}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}function dateInput(){return `<input aria-label="Log date" class="date-pill" type="date" style="width:145px" value="${selectedDate}" onchange="selectedDate=this.value||today();render()">`}
function macros(t){return [['Protein',t.p,state.profile.protein,'#639c80'],['Carbs',t.c,state.profile.carbs,'#d6a16c'],['Fat',t.f,state.profile.fat,'#a393cb']].map(([n,v,g,c])=>`<div class="macro"><div class="macro-line"><strong><i class="macro-dot" style="background:${c}"></i>${n}</strong><span>${round(v)} / ${g} g</span></div><div class="bar"><span style="width:${pct(v,g)}%;background:${c}"></span></div></div>`).join('')}
function mealRows(items,editable=false){return items.length?items.map(m=>`<div class="meal-row"><div class="food-icon">${esc(m.icon||'🍽️')}</div><div class="meal-info"><strong>${esc(m.name)}</strong><small>${esc(m.meal)} · ${round(m.p)}g protein${m.amount?' · '+m.amount+' '+esc(m.unit||'g'):m.grams?' · '+m.grams+'g':''}</small></div><div class="meal-cal">${round(m.cal)} <small>kcal</small></div>${editable?`<button class="text-btn" onclick="mealModal('${m.id}')" aria-label="Edit ${esc(m.name)}">Edit</button>`:''}</div>`).join(''):'<div class="empty"><strong>A fresh start.</strong>Add your first meal to see your day take shape.</div>'}
function dashboard(){let t=sum(today()),p=state.profile,water=state.water[today()]||0,logged=state.sessions.filter(s=>Date.now()-new Date(s.date+'T12:00:00').getTime()<7*864e5).length;return title('A little better, every day',`Let's make progress${p.name?', '+esc(p.name.split(' ')[0]):''}.`,'A clear picture of your nutrition, movement, and momentum.',`<div class="date-pill">◷ ${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</div>`)+(!calculateNutrition(p)?'<div class="section-note">Complete your profile to set your nutrition goals. <button class="text-btn" onclick="onboarding()">Set up your profile →</button></div>':'')+`<div class="grid stats"><div class="card"><div class="stat-head">Calories logged <span class="stat-icon">♨</span></div><div class="stat-value">${round(t.cal).toLocaleString()}<small>/ ${p.cal} kcal</small></div><div class="bar"><span style="width:${pct(t.cal,p.cal)}%"></span></div><div class="stat-foot">${Math.abs(round(p.cal-t.cal))} kcal ${t.cal>p.cal?'above target':'remaining'}</div></div><div class="card"><div class="stat-head">Protein <span class="stat-icon">◈</span></div><div class="stat-value">${round(t.p)}<small>/ ${p.protein} g</small></div><div class="bar"><span style="width:${pct(t.p,p.protein)}%;background:#9abca8"></span></div><div class="stat-foot">Your daily protein progress</div></div><div class="card"><div class="stat-head">Training this week <span class="stat-icon">⌁</span></div><div class="stat-value">${logged}<small>/ ${p.days} sessions</small></div><div class="stat-foot"><span class="status-pip"></span> Keep showing up for yourself</div></div><div class="card"><div class="stat-head">Water <button class="text-btn" onclick="addWater()" aria-label="Add 250 milliliters of water">+ 250 ml</button></div><div class="stat-value">${(water/1000).toFixed(2)}<small>litres logged</small></div><div class="stat-foot">Tap + to log a glass</div></div></div><div class="grid dashboard"><div class="stack"><div class="card"><div class="card-head"><h2>Nutrition overview</h2><span class="small-muted">Today</span></div><div class="nutrition-layout"><div class="ring" style="--pct:${pct(t.cal,p.cal)}%"><div class="ring-inner"><b>${Math.max(0,round(p.cal-t.cal))}</b><small>kcal remaining</small></div></div><div class="macros">${macros(t)}</div></div><div class="card-bottom"><span>Small choices. Consistent progress.</span><button class="text-btn" onclick="go('food')">View food diary ↗</button></div></div><div class="card"><div class="card-head"><h2>On your plate</h2><button class="text-btn" onclick="selectedDate=today();mealModal()">+ Add food</button></div>${mealRows(state.meals.filter(m=>m.date===today()).slice(-3))}</div><div class="card"><div class="card-head"><h2>Your rhythm</h2><span class="small-muted">Last 7 days</span></div><div class="week">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;let done=state.sessions.some(s=>s.date===key);return `<button type="button" aria-label="View ${key}" aria-pressed="${rhythmDate===key}" onclick="selectRhythmDay('${key}')" class="day ${rhythmDate===key?'selected':''} ${done?'done':''} ${i===6?'today':''}">${d.toLocaleDateString(undefined,{weekday:'narrow'})}<span>${done?'✓':d.getDate()}</span></button>`}).join('')}</div><div id="rhythm-summary">${rhythmSummary(rhythmDate)}</div></div></div><div class="stack">${todayTrainingCard()}<div class="card coach-card"><div class="card-head"><div style="display:flex;gap:10px;align-items:center"><span class="coach-icon">✧</span><h2>A little guidance</h2></div><span class="tag">PREVIEW</span></div><h3>Your data. A more personal coach.</h3><p>Explore what a weekly review could look like. Live AI coaching will arrive when the backend is connected.</p><button class="text-btn" onclick="go('coach')">Meet your AI coach ↗</button></div></div></div>`}
function addWater(){state.water[today()]=(state.water[today()]||0)+250;save();render();toast('250 ml added')}
function foodPage(){let t=sum();return title('Nutrition','Your food diary.','Every meal is part of the bigger picture.',dateInput())+`<div class="grid dashboard"><div class="stack"><div class="card"><div class="card-head"><h2>Meals & snacks</h2><button class="btn small" onclick="mealModal()">+ Add food</button></div>${['Breakfast','Lunch','Dinner','Snack'].map(n=>`<div style="margin:18px 0"><div class="eyebrow" style="color:#8c958f">${n}</div>${mealRows(state.meals.filter(m=>m.date===selectedDate&&m.meal===n),true)}</div>`).join('')}</div></div><div class="stack"><div class="card"><div class="card-head"><h2>Daily balance</h2><span class="small-muted">${dateText(selectedDate)}</span></div><div class="stat-value">${round(t.cal)}<small>/ ${state.profile.cal} kcal</small></div>${macros(t)}</div><div class="card"><h2>More ways to log</h2><p class="small-muted">Manual entries and the sample food library work now.</p>${[['▦','Barcode scanning'],['◉','Meal photo analysis'],['✧','Describe a meal']].map(([i,n])=>`<div class="connection"><span>${i} &nbsp; ${n}</span><span class="soon">BACKEND PLANNED</span></div>`).join('')}<p class="small-muted">Sample food values are illustrative per 100 g. Check the package for your product.</p></div></div></div>`}
function legacyFoodEntryModal(id=null,mode='manual'){editId=id;mealMode=mode;const m=state.meals.find(m=>m.id===id)||{name:'',meal:'Breakfast',cal:'',p:'',c:'',f:'',grams:100};modal(modalHead(id?'Edit food':'Add something nourishing')+(!id?`<div class="tabs" style="margin-top:20px"><button class="tab ${mode==='manual'?'active':''}" onclick="mealModal(null,'manual')">Manual entry</button><button class="tab ${mode==='library'?'active':''}" onclick="mealModal(null,'library')">Sample food library</button></div>`:'')+`<form onsubmit="saveMeal(event)">${mode==='library'?`<label for="food-search">Find a sample food</label><input id="food-search" placeholder="Search oats, tofu, rice…" oninput="filterFoods(this.value)"><label for="food-choice">Food · values per 100 g</label><select id="food-choice" onchange="fillFood()">${foods.map((f,i)=>`<option value="${i}">${f.name}</option>`).join('')}</select><label for="grams">Quantity (g)</label><input id="grams" type="number" min="1" max="10000" value="100" required oninput="fillFood()">`:''}<div class="form-grid"><div class="wide"><label for="meal-name">Food / meal name</label><input id="meal-name" required maxlength="150" value="${esc(m.name)}" placeholder="e.g. Tofu and rice bowl"></div><div><label for="meal-type">Meal</label><select id="meal-type">${['Breakfast','Lunch','Dinner','Snack'].map(t=>`<option ${m.meal===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="meal-cal">Calories (kcal)</label><input id="meal-cal" type="number" min="0" max="20000" step="any" value="${m.cal}" required></div>${[['p','Protein'],['c','Carbs'],['f','Fat']].map(([k,n])=>`<div><label for="meal-${k}">${n} (g)</label><input id="meal-${k}" type="number" min="0" max="2000" step="any" value="${m[k]}" required></div>`).join('')}</div><div class="actions">${id?`<button type="button" class="btn danger" onclick="deleteMeal('${id}')">Delete</button>`:''}<button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn">Save food</button></div></form>`);if(mode==='library')fillFood()}
function filterFoods(q){$('#food-choice').innerHTML=foods.map((f,i)=>({f,i})).filter(x=>x.f.name.toLowerCase().includes(q.toLowerCase())).map(({f,i})=>`<option value="${i}">${f.name}</option>`).join('');fillFood()}
function fillFood(){let f=foods[$('#food-choice').value];if(!f)return;let q=Number($('#grams').value)/100;$('#meal-name').value=f.name;['cal','p','c','f'].forEach(k=>$('#meal-'+k).value=Math.round(f[k]*q*10)/10)}
function saveMeal(e){e.preventDefault();let previous=state.meals.find(m=>m.id===editId),m={id:editId||uid(),date:previous?.date||selectedDate,name:$('#meal-name').value.trim(),meal:$('#meal-type').value,icon:mealMode==='library'?foods[$('#food-choice').value]?.icon:'🍽️'};if(!m.name)return;['cal','p','c','f'].forEach(k=>m[k]=Number($('#meal-'+k).value));if(mealMode==='library')m.grams=Number($('#grams').value);if(editId)state.meals=state.meals.map(x=>x.id===editId?m:x);else state.meals.push(m);save();closeModal();render();toast('Food diary updated')}
function deleteMeal(id){state.meals=state.meals.filter(m=>m.id!==id);save();closeModal();render();toast('Entry deleted')}
function baseWorkoutPage(){return title('Training','Your training, your way.','Start in the moment. Build routines that work for you.',`<button class="btn secondary" onclick="openHevyImport()">↓ Import from Hevy</button>`)+(state.active?activeWorkout():`<button class="start-workout-card" onclick="startWorkout()"><span class="start-symbol">＋</span><span><strong>Start Workout</strong><small>Add exercises as you train.</small></span><span class="start-arrow">→</span></button><section class="routine-section"><div class="card-head"><h2>Routines</h2><button class="icon-btn" aria-label="Create folder" title="Create folder" onclick="folderModal()">${folderIcon()} <span class="folder-add">+</span></button></div>${state.routines.filter(r=>!r.folderId||!state.folders.some(f=>f.id===r.folderId)).map(routineCard).join('')}${state.folders.map(f=>`<div class="folder"><button class="folder-toggle" aria-expanded="${!!state.folderOpen[f.id]}" onclick="toggleFolder('${f.id}')"><span>${folderIcon()}</span><span class="folder-title">${esc(f.name)}<small>${state.routines.filter(r=>r.folderId===f.id).length} routines</small></span><span>${state.folderOpen[f.id]?'⌃':'⌄'}</span></button>${state.folderOpen[f.id]?`<div class="folder-content">${state.routines.filter(r=>r.folderId===f.id).map(routineCard).join('')}<button class="create-routine" onclick="routineModal(null,'${f.id}')">＋ Create New Routine</button></div>`:''}</div>`).join('')}<button class="create-routine" onclick="chooseRoutineLocation()">＋ Create Routine</button>${!state.routines.length&&!state.folders.length?'<p class="empty-hint">Your space is ready. Create a routine or organize your training into folders.</p>':''}</section>`)+`<div class="card" style="margin-top:22px"><div class="card-head"><h2>Session history</h2><span class="small-muted">${state.sessions.length} completed</span></div>${state.sessions.length?state.sessions.slice().reverse().map(s=>`<div class="connection"><div><strong>${esc(s.name)}</strong><p>${dateText(s.date)} · ${s.sets.length} completed sets · ${round(s.sets.reduce((n,x)=>n+x.kg*x.reps,0))} kg volume</p></div><button class="text-btn" onclick="sessionDetail('${s.id}')">Details ↗</button></div>`).join(''):'<div class="empty">Your completed sessions will appear here.</div>'}</div>`}

function legacyRoutineModal(id,folderId=null,sessionId=null){let r=state.routines.find(r=>r.id===id);if(sessionId){let session=state.sessions.find(s=>s.id===sessionId);r={name:session.name,exercises:[...new Set(session.sets.map(x=>x.group))].map(g=>{let sets=session.sets.filter(x=>x.group===g);return {name:sets[0].exercise,sets:sets.length,reps:sets[0].reps,rest:session.rest?.[g]?.duration||90}})};}routineRestDraft=r?.exercises.map(e=>e.rest||90)||[];modal(modalHead(r?'Edit routine':'Create a routine')+`<form onsubmit="saveRoutine(event,'${id||''}')"><label for="routine-name">Routine name</label><input id="routine-name" required maxlength="100" value="${esc(r?.name||'')}"><label for="routine-folder">Location</label><select id="routine-folder"><option value="">Without a folder</option>${state.folders.map(f=>`<option value="${f.id}" ${(r?.folderId||folderId)===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select><label for="routine-exercises">Exercises · one per line</label><textarea id="routine-exercises" rows="7" required placeholder="Squat, 3, 8\nBench press, 3, 10">${esc(r?.exercises.map(e=>`${e.name}, ${e.sets}, ${e.reps}`).join('\n')||'')}</textarea><p class="small-muted">Format: Exercise name, sets, reps. Example: Squat, 3, 8</p><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn">Save routine</button></div></form>`)}
function saveRoutine(e,id){e.preventDefault();let lines=$('#routine-exercises').value.split('\n').filter(x=>x.trim()),exercises=[];for(const l of lines){const parts=l.split(',');let name=parts.slice(0,-2).join(',').trim(),sets=Number(parts.at(-2)),reps=Number(parts.at(-1));if(!name||!Number.isInteger(sets)||sets<1||sets>20||!Number.isInteger(reps)||reps<1||reps>100){toast('Use: Exercise name, sets (1–20), reps (1–100)');return}exercises.push({name,sets,reps,kg:0})}if(!exercises.length)return;let old=state.routines.find(x=>x.id===id);exercises.forEach((ex,i)=>{ex.rest=old?.exercises.find(x=>x.name===ex.name)?.rest||routineRestDraft[i]||90});let r={id:id||uid(),name:$('#routine-name').value.trim(),exercises,folderId:$('#routine-folder').value||null};state.routines=id?state.routines.map(x=>x.id===id?r:x):[...state.routines,r];if(r.folderId)state.folderOpen[r.folderId]=true;save();closeModal();render();toast('Routine saved')}
function startWorkout(id){if(!state.active){let r=id?state.routines.find(r=>r.id===id):null;state.active={id:uid(),name:r?.name||'Workout',routineId:r?.id||null,unplanned:!r,date:today(),started:Date.now(),rest:r?Object.fromEntries(r.exercises.map((e,i)=>[i,{duration:e.rest??90,end:0}])):{},sets:r?r.exercises.flatMap((e,i)=>Array.from({length:e.sets},(_,j)=>({exercise:e.name,catalogId:e.catalogId||null,catalogSource:e.catalogSource||null,group:i,set:j+1,reps:e.reps,kg:e.kg,done:false}))):[]};}save();go('workouts')}

function activeWorkout(){let a=state.active;return `<div class="card"><div class="card-head"><div><div class="eyebrow">SESSION IN PROGRESS</div><h2>${esc(a.name)}</h2></div><button class="text-btn" onclick="cancelWorkout()">Discard</button></div>${[...new Set(a.sets.map(s=>s.group))].map(g=>`<div class="routine"><h3>${esc(a.sets.find(s=>s.group===g).exercise)}</h3>${exerciseRestUI(g)}<div class="set-row"><small>SET</small><small>WEIGHT · KG</small><small>REPS</small><small>DONE</small></div>${a.sets.map((s,i)=>s.group===g?`<div class="set-row"><span>${s.set}</span><input aria-label="${esc(s.exercise)} set ${s.set} weight" type="number" min="0" max="2000" step=".5" value="${s.kg}" onchange="updateSet(${i},'kg',this.value)"><input aria-label="${esc(s.exercise)} set ${s.set} reps" type="number" min="1" max="1000" value="${s.reps}" onchange="updateSet(${i},'reps',this.value)"><button aria-label="Mark set ${s.set} complete" aria-pressed="${s.done}" class="check-set ${s.done?'checked':''}" onclick="toggleSet(${i})">✓</button></div>`:'').join('')}</div>`).join('')}<button class="btn secondary full" onclick="addExerciseModal()">＋ Add Exercise</button><button class="btn full" onclick="finishWorkout()">Finish & save session (${a.sets.filter(s=>s.done).length} sets)</button></div>`}
function updateSet(i,k,v){v=Number(v);if(!Number.isFinite(v)||v<(k==='reps'?1:0)||v>(k==='reps'?1000:2000)){toast('Enter a valid '+k);render();return}state.active.sets[i][k]=v;save()}function toggleSet(i){state.active.sets[i].done=!state.active.sets[i].done;save();render()}function finishWorkout(){let a=state.active;if(!a.sets.some(s=>s.done)){toast('Mark at least one set complete first');return}state.sessions.push({...a,sets:a.sets.filter(s=>s.done),finished:Date.now()});state.active=null;startTimer(0);save();render();toast('Session saved. Nice work showing up!');if(a.unplanned)offerSaveRoutine(a.id)}function cancelWorkout(){modal(modalHead('Discard this session?')+'<p class="small-muted">This removes the unfinished sets from this session.</p><div class="actions"><button class="btn secondary" onclick="closeModal()">Keep training</button><button class="btn danger" onclick="state.active=null;save();closeModal();render()">Discard session</button></div>')}
function timerLabel(){let n=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}function startTimer(s){clearInterval(timerInterval);timerEnd=s?Date.now()+s*1000:0;if($('#timer-text'))$('#timer-text').textContent=timerLabel();if(s)timerInterval=setInterval(()=>{if($('#timer-text'))$('#timer-text').textContent=timerLabel();if(Date.now()>=timerEnd){clearInterval(timerInterval);toast('Rest complete. Ready for your next set?')}},500)}
function sessionDetail(id){let s=state.sessions.find(s=>s.id===id);modal(modalHead(esc(s.name))+`<p class="small-muted">${dateText(s.date)} · ${Math.round((s.finished-s.started)/60000)} minutes</p><table class="history-table"><tr><th>Exercise</th><th>kg</th><th>Reps</th></tr>${s.sets.map(x=>`<tr><td>${esc(x.exercise)} · ${x.set}</td><td>${x.kg}</td><td>${x.reps}</td></tr>`).join('')}</table><div class="actions"><button class="btn" onclick="closeModal()">Done</button></div>`)}
function weightChart(){let w=state.weights.slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-14);if(!w.length)return '<div class="empty"><strong>A trend starts with one check-in.</strong>Log your weight to build your chart.</div>';let min=Math.min(...w.map(x=>x.kg))-1,max=Math.max(...w.map(x=>x.kg))+1;let pts=w.map((x,i)=>[45+i*(510/Math.max(1,w.length-1)),155-(x.kg-min)/(max-min)*125]);return `<svg viewBox="0 0 590 200" class="chart" role="img" aria-label="Weight trend from ${w[0].kg} to ${w.at(-1).kg} kilograms">${[0,1,2].map(i=>`<line x1="45" x2="555" y1="${30+i*62.5}" y2="${30+i*62.5}" stroke="#edf0ed"/><text x="5" y="${34+i*62.5}">${(max-(max-min)*i/2).toFixed(1)}</text>`).join('')}<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#398664" stroke-width="2.5"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#398664"><title>${w[i].date}: ${w[i].kg} kg</title></circle>`).join('')}<text x="45" y="190">${dateText(w[0].date)}</text><text x="510" y="190">${dateText(w.at(-1).date)}</text></svg>`}
function bodyProgressPage(){let w=state.weights.slice().sort((a,b)=>a.date.localeCompare(b.date)),volume=state.sessions.reduce((n,s)=>n+s.sets.reduce((v,x)=>v+x.kg*x.reps,0),0);return title('The bigger picture','Progress, beyond a single day.','Look for patterns. Give yourself time.',`<button class="btn" onclick="checkinModal()">+ Check in</button>`)+`<div class="grid stats"><div class="card"><div class="stat-head">Latest weight</div><div class="stat-value">${w.length?w.at(-1).kg:'—'}<small>kg</small></div><div class="stat-foot">${w.length?dateText(w.at(-1).date):'No check-ins yet'}</div></div><div class="card"><div class="stat-head">Weight change</div><div class="stat-value">${w.length>1?(w.at(-1).kg-w[0].kg).toFixed(1):'—'}<small>kg</small></div><div class="stat-foot">Across your logged check-ins</div></div><div class="card"><div class="stat-head">Sessions completed</div><div class="stat-value">${state.sessions.length}</div><div class="stat-foot">Every session counts</div></div><div class="card"><div class="stat-head">Total training volume</div><div class="stat-value">${round(volume).toLocaleString()}<small>kg</small></div><div class="stat-foot">Completed reps × logged weight</div></div></div><div class="grid two"><div class="card"><div class="card-head"><h2>Weight trend</h2><span class="small-muted">Latest 14 check-ins · kg · includes samples if loaded</span></div><div class="chart-area">${weightChart()}</div></div><div class="card"><div class="card-head"><h2>Recovery & activity</h2><span class="tag">MANUAL LOGGING</span></div>${state.checkins.length?state.checkins.slice(-3).reverse().map(c=>`<div class="connection"><div><strong>${dateText(c.date)}</strong><p>${c.steps||'—'} steps · ${c.sleep||'—'}h sleep · ${c.waist||'—'}cm waist</p><p>${esc(c.note)}</p></div></div>`).join(''):'<div class="empty"><strong>Recovery is part of training.</strong>Add sleep, steps, and measurements with a check-in.</div>'}</div></div><div class="card" style="margin-top:20px"><h2>Check-in history</h2>${w.length?`<table class="history-table"><tr><th>Date</th><th>Weight</th><th></th></tr>${w.slice().reverse().map(x=>`<tr><td>${dateText(x.date)}</td><td>${x.kg} kg</td><td><button class="text-btn" onclick="deleteCheckin('${x.id}')">Delete</button></td></tr>`).join('')}</table>`:'<div class="empty">Your measurements will appear here.</div>'}</div>`}
function checkinModal(){modal(modalHead('A moment to check in')+`<form onsubmit="saveCheckin(event)"><div class="form-grid"><div><label for="check-date">Date</label><input id="check-date" type="date" value="${today()}" required></div><div><label for="check-weight">Weight (kg)</label><input id="check-weight" type="number" min="20" max="400" step=".1"></div><div><label for="check-sleep">Sleep (hours)</label><input id="check-sleep" type="number" min="0" max="24" step=".1"></div><div><label for="check-steps">Steps</label><input id="check-steps" type="number" min="0" max="200000"></div><div><label for="check-waist">Waist (cm)</label><input id="check-waist" type="number" min="20" max="300" step=".1"></div><div class="wide"><label for="check-note">How are you feeling?</label><textarea id="check-note" maxlength="2000" placeholder="Energy, recovery, anything worth noting…"></textarea></div></div><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn">Save check-in</button></div></form>`)}
function saveCheckin(e){e.preventDefault();let id=uid(),date=$('#check-date').value,kg=$('#check-weight').value,sleep=$('#check-sleep').value,steps=$('#check-steps').value,waist=$('#check-waist').value,note=$('#check-note').value;if(!kg&&!sleep&&!steps&&!waist&&!note.trim()){toast('Add at least one measurement or a note');return}if(kg)state.weights.push({id,date,kg:Number(kg)});state.checkins.push({id,date,sleep,steps,waist,note});save();closeModal();render();toast('Check-in saved')}function deleteCheckin(id){state.weights=state.weights.filter(x=>x.id!==id);state.checkins=state.checkins.filter(x=>x.id!==id);save();render();toast('Check-in removed')}
function coachPage(){return title('A thoughtful training partner','Meet your future coach.','A place to reflect, ask questions, and plan your next step.')+`<div class="section-note"><strong>Interactive preview · No LLM connected.</strong> Replies below are local templates using simple log totals. They do not analyze your health or create personalized recommendations.</div><div class="grid dashboard"><div class="card"><div class="card-head"><div style="display:flex;gap:10px;align-items:center"><span class="coach-icon">✧</span><h2>My Fitness Diary coach</h2></div><span class="tag">DEMO</span></div><div class="chat" id="chat-messages"><div class="message">Hi${state.profile.name?' '+esc(state.profile.name):''}! This is a preview of your coaching space. I can show a simple summary of your local logs. When connected, your chosen LLM will be able to help interpret them.</div>${state.chat.map(m=>`<div class="message ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')}</div><div class="suggestions"><button onclick="sendDemo('Review my week')">Review my week</button><button onclick="sendDemo('Show my nutrition summary')">Nutrition summary</button><button onclick="sendDemo('Help plan my training')">Plan my training</button></div><form class="chat-form" onsubmit="event.preventDefault();sendDemo($('#chat-input').value)"><input id="chat-input" required maxlength="1000" aria-label="Message the demo coach" placeholder="Ask your coach…"><button class="btn">Send ↗</button></form></div><div class="stack"><div class="card coach-card"><div class="eyebrow">The plan</div><h2>Coaching with context.</h2><p>The connected coach will use your goals, food diary, training history, and recovery data to support a more useful conversation.</p><div class="connection"><span>Weekly reviews</span><span>↗</span></div><div class="connection"><span>Explainable plan changes</span><span>↗</span></div><div class="connection"><span>Your choice of LLM</span><span>↗</span></div></div><div class="card"><h2>Your information, your call.</h2><p class="small-muted">No data leaves this app for AI processing in this version. API keys and real coaching will be added with the backend.</p><button class="text-btn" onclick="go('settings')">View planned connections →</button></div></div></div>`}
function sendDemo(text){text=text.trim();if(!text)return;let t=sum(today()),week=state.sessions.filter(s=>Date.now()-new Date(s.date+'T12:00:00')<7*864e5).length;let reply;if(/week|review/i.test(text))reply=`Demo weekly snapshot: you completed ${week} workout session(s) in the last 7 days and have ${state.weights.length} weight check-in(s) in this browser.\n\nA connected coach would look at consistency, training progression, and recovery together before proposing changes.`;else if(/food|nutrition|protein|calorie|meal/i.test(text))reply=`Demo nutrition snapshot for today: ${round(t.cal)} kcal, ${round(t.p)}g protein, ${round(t.c)}g carbs, and ${round(t.f)}g fat logged.\n\nYour configured targets are ${state.profile.cal} kcal and ${state.profile.protein}g protein. These are calculated starting estimates from your profile, not an AI assessment.`;else if(/train|workout|routine/i.test(text))reply=`You have ${state.routines.length} routine(s) and a goal of ${state.profile.days} sessions per week. You can edit routines and log real sessions in Training now.\n\nPersonalized program generation will become available after connecting an LLM and completing your profile.`;else reply='This preview cannot interpret free-form questions yet. Try “Review my week” or “Show my nutrition summary” to see a summary from your saved entries. Your message stays in this browser.';state.chat.push({role:'user',text},{role:'assistant',text:reply});save();render();$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight}
function profileFields(onboard=false){let p=state.profile;return `<div class="form-grid"><div><label for="p-name">Your name</label><input id="p-name" required maxlength="80" value="${esc(p.name)}" placeholder="What should we call you?"></div><div><label for="p-goal">Primary goal</label><select id="p-goal">${['Lose fat','Build muscle','Improve strength','Body recomposition'].map(x=>`<option ${p.goal===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label for="p-weight">Current weight (kg)</label><input id="p-weight" required type="number" min="20" max="400" step=".1" value="${p.weight}"></div><div><label for="p-height">Height (cm)</label><input id="p-height" required type="number" min="100" max="250" value="${p.height}"></div><div><label for="p-target">Target weight (kg, optional)</label><input id="p-target" type="number" min="20" max="400" step=".1" value="${p.target}"></div><div><label for="p-days">Training days per week</label><input id="p-days" type="number" required min="1" max="7" value="${p.days}"></div><div><label for="p-experience">Training experience</label><select id="p-experience">${['Beginner','Intermediate','Advanced'].map(x=>`<option ${p.experience===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label for="p-equipment">Equipment</label><select id="p-equipment">${['Gym','Home weights','Bodyweight'].map(x=>`<option ${p.equipment===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="wide"><label for="p-diet">Dietary preferences</label><input id="p-diet" maxlength="300" value="${esc(p.diet)}" placeholder="Vegetarian, allergies, favorite foods…"></div><div class="wide"><label for="p-limitations">Limitations & schedule notes</label><textarea id="p-limitations" maxlength="2000" placeholder="Anything a future coach should know">${esc(p.limitations)}</textarea></div></div><div class="form-grid" oninput="updateNutritionPreview()" onchange="updateNutritionPreview()"><div><label for="p-age">Age (years)</label><input id="p-age" required type="number" min="18" max="100" value="${esc(p.age||'')}"></div><div><label for="p-sex">Sex used for calorie estimation</label><select id="p-sex" required><option value="">Select…</option><option value="male" ${p.sex==='male'?'selected':''}>Male</option><option value="female" ${p.sex==='female'?'selected':''}>Female</option></select></div><div class="wide"><label for="p-activity">Overall activity (including workouts)</label><select id="p-activity" required><option value="">Select…</option>${[['1.2','Mostly seated · little exercise'],['1.375','Light · easy activity 1–3 days/week'],['1.55','Moderate · exercise 3–5 days/week'],['1.725','High · hard exercise 6–7 days/week'],['1.9','Very high · physical job & hard training']].map(([v,t])=>`<option value="${v}" ${String(p.activity)===v?'selected':''}>${t}</option>`).join('')}</select></div></div><h3 style="margin-top:25px">Your calculated daily targets</h3><div id="nutrition-preview" aria-live="polite">${nutritionPreview(p)}</div>`}
function onboarding(){modal(modalHead('Let’s make this your space.')+'<div class="onboard-intro">Tell us what you’re working toward. Your profile stays editable, and every entry is stored locally.</div><form onsubmit="saveProfile(event,true)">'+profileFields(true)+'<div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">Explore first</button><button class="btn">Save & get started →</button></div></form>')}
function saveProfile(e,inModal=false){e.preventDefault();let profile={...state.profile};for(const k of ['name','goal','weight','height','target','days','experience','equipment','diet','limitations','age','sex','activity']){let v=$('#p-'+k).value;profile[k]=['days','age','activity'].includes(k)?Number(v):v.trim()}let targets=calculateNutrition(profile);if(!targets){toast('Complete age, sex, weight, height, and activity to calculate targets');return}state.profile={...profile,...targets,onboarded:true};save();if(inModal)closeModal();render();toast('Profile saved · nutrition targets calculated')}

function baseSettingsPage(){return title('Your preferences','Make My Fitness Diary yours.','Your goals today can change. Your tools should adapt.')+`<div class="grid two"><div class="card"><div class="card-head"><h2>Profile & goals</h2><span class="tag" id="profile-storage-label">LOCAL PROFILE</span></div><form onsubmit="saveProfile(event)">${profileFields()}<button class="btn full">Save changes</button></form></div><div class="stack"><div class="card"><h2>Accounts & connections</h2><button class="btn soft full" onclick="openAccount()">Manage account & cloud sync</button><p class="small-muted">Accounts and PostgreSQL are connected. AI and wearable integrations remain planned.</p>${[['Identity','Supabase Auth · email login; Google needs setup'],['Database','Supabase PostgreSQL · private workspace sync'],['AI providers','Provider adapters · per-user API keys'],['Apple Health','Requires an iOS bridge'],['Samsung Health','Requires an Android / Health Connect bridge'],['Reminders','Background delivery service']].map(([n,d])=>`<div class="connection"><div><strong>${n}</strong><p>${d}</p></div><span class="soon">${['Identity','Database'].includes(n)?'CONNECTED':'PLANNED'}</span></div>`).join('')}</div><div class="card"><h2>Your data</h2><p class="small-muted">Sign in for your private cloud workspace. Browser-only data stays local until you choose to upload it. A local account cache remains on this device; export backups before bulk changes.</p><div class="actions" style="justify-content:flex-start"><button class="btn secondary" onclick="exportData()">Export JSON ↓</button><button class="btn secondary" onclick="$('#import-file').click()">Import backup ↑</button><input type="file" id="import-file" accept="application/json" hidden onchange="importData(this.files[0])"></div><div class="connection"><div><strong>Explore a filled dashboard</strong><p>Add clearly labeled sample meals and check-ins.</p></div><button class="text-btn" onclick="loadSamples()">Add samples</button></div><button class="text-btn" style="color:#b15e5e;margin-top:15px" onclick="resetModal()">Reset local workspace</button></div></div></div>`}
function exportData(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='forma-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported')}
function validBackup(d){if(!d||typeof d!=='object'||!d.profile||!['meals','weights','sessions','routines','checkins','chat'].every(k=>Array.isArray(d[k])))return false;if(!d.routines.every(r=>typeof r.id==='string'&&typeof r.name==='string'&&Array.isArray(r.exercises)&&r.exercises.length&&r.exercises.every(e=>typeof e.name==='string'&&Number.isInteger(e.sets)&&e.sets>0&&e.sets<=20&&Number.isFinite(e.reps))))return false;if(!['cal','protein','carbs','fat','days'].every(k=>Number.isFinite(d.profile[k])&&d.profile[k]>0))return false;if(!d.meals.every(m=>typeof m.id==='string'&&typeof m.date==='string'&&typeof m.name==='string'&&['cal','p','c','f'].every(k=>Number.isFinite(m[k])&&m[k]>=0)))return false;if(!d.weights.every(w=>typeof w.date==='string'&&Number.isFinite(w.kg)))return false;if(!d.sessions.every(s=>typeof s.name==='string'&&typeof s.date==='string'&&Array.isArray(s.sets)&&s.sets.every(x=>typeof x.exercise==='string'&&(x.kg==null||Number.isFinite(x.kg))&&(x.reps==null||Number.isFinite(x.reps)))))return false;return true}
async function importData(file){if(!file)return;try{if(file.size>5000000)throw Error();let d=JSON.parse(await file.text());if(!validBackup(d))throw Error();modal(modalHead('Replace this workspace?')+'<p class="small-muted">Importing replaces your current local entries. Export first if you want to keep them.</p><div class="actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button id="confirm-import" class="btn">Replace & import</button></div>');$('#confirm-import').onclick=()=>{state={...defaults(),...d,active:null,water:d.water&&typeof d.water==='object'?d.water:{}};save();closeModal();render();toast('Backup imported')}}catch{toast('This is not a supported My Fitness Diary backup')}}
function localResetModal(){modal(modalHead('Start fresh?')+'<p class="small-muted">This deletes all entries from this browser. Export a backup first if you want to keep them.</p><div class="actions"><button class="btn secondary" onclick="closeModal()">Keep my data</button><button class="btn danger" onclick="state=defaults();save();closeModal();go(\'today\');toast(\'Workspace reset\')">Delete local data</button></div>')}
function loadSamples(){if(state.meals.some(m=>m.sample)){toast('Sample data is already loaded');return}let id=uid();state.meals.push({id:uid(),date:today(),name:'Sample · Oats, yogurt & banana',meal:'Breakfast',cal:480,p:28,c:66,f:11,icon:'🥣',sample:true},{id:uid(),date:today(),name:'Sample · Tofu rice bowl',meal:'Lunch',cal:610,p:35,c:72,f:20,icon:'🥢',sample:true});for(let i=6;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);let date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;state.weights.push({id:uid(),date,kg:Math.round((70-i*.08+Math.sin(i)*.12)*10)/10,sample:true})}save();render();toast('Sample entries added — meals are labeled Sample')}
document.addEventListener('input',e=>{if(e.target.id?.startsWith('p-'))updateNutritionPreview()});document.addEventListener('change',e=>{if(e.target.id?.startsWith('p-'))updateNutritionPreview()});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});page=links.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'today';render();
function calculateNutrition(p){let w=Number(p.weight),h=Number(p.height),age=Number(p.age),activity=Number(p.activity);if(!(w>=20&&w<=400&&h>=100&&h<=250&&age>=18&&age<=100&&['male','female'].includes(p.sex)&&[1.2,1.375,1.55,1.725,1.9].includes(activity)))return null;let resting=10*w+6.25*h-5*age+(p.sex==='male'?5:-161),maintenance=Math.round(resting*activity),adjustment=({'Lose fat':.85,'Build muscle':1.08,'Improve strength':1,'Body recomposition':1})[p.goal]??1;let cal=Math.round(maintenance*adjustment/10)*10;cal=Math.max(p.sex==='male'?1500:1200,cal);let protein=Math.min(Math.round(w*(p.goal==='Lose fat'?2:1.6)),Math.floor(cal*.35/4)),fat=Math.round(cal*.28/9),carbs=Math.max(0,Math.round((cal-protein*4-fat*9)/4));return {cal,protein,fat,carbs,maintenance,resting:Math.round(resting),nutritionMethod:'mifflin-v1'}}
function nutritionPreview(p){let n=calculateNutrition(p);if(!n)return '<div class="section-note">Complete your weight, height, age, sex, and overall activity above. My Fitness Diary will calculate your calorie and macro targets automatically.</div>';return `<div class="target-grid">${[['Calories',n.cal,'kcal'],['Protein',n.protein,'g'],['Carbs',n.carbs,'g'],['Fat',n.fat,'g']].map(([t,v,u])=>`<div><span>${t}</span><strong>${v}<small> ${u}</small></strong></div>`).join('')}</div><p class="small-muted">Estimated maintenance: ${n.maintenance} kcal/day. ${p.goal==='Lose fat'?'Fat loss starts with a 15% deficit.':p.goal==='Build muscle'?'Muscle gain starts with an 8% surplus.':'This goal starts near maintenance calories.'} Activity includes workouts; exercise calories are not added twice. Minimum calorie guardrails may reduce the deficit.</p><details class="small-muted"><summary>How these estimates work</summary><p>Mifflin–St Jeor resting energy × selected activity factor, then a goal adjustment. Protein starts at 1.6 g/kg (2.0 for fat loss), capped at 35% of calories; fat uses approximately 28%; carbohydrates use the remainder. These app defaults are starting estimates, not a guarantee of results. Review trends before adjusting your profile. Target weight is recorded as a goal, not used to create an aggressive deadline. Adult estimates are not designed for pregnancy or breastfeeding.</p><p><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener">Calorie equation ↗</a> · <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5477153/" target="_blank" rel="noopener">Protein reference ↗</a></p></details>`}
function updateNutritionPreview(){let box=$('#nutrition-preview');if(!box)return;let p={};for(const k of ['weight','height','age','sex','activity','goal'])p[k]=$('#p-'+k)?.value;box.innerHTML=nutritionPreview(p)}
function selectRhythmDay(date){rhythmDate=date;render()}
function rhythmSummary(date){let t=sum(date),sessions=state.sessions.filter(s=>s.date===date),meals=state.meals.filter(m=>m.date===date),check=state.checkins.filter(c=>c.date===date).at(-1),water=state.water[date]||0;return `<div class="rhythm-detail"><div class="card-head"><strong>${date===today()?'Today':dateText(date)}</strong><span class="small-muted">${sessions.length?'Training day':'No workout logged'}</span></div><div class="rhythm-metrics"><span><strong>${round(t.cal)}</strong> kcal</span><span><strong>${round(t.p)}g</strong> protein</span><span><strong>${sessions.length}</strong> sessions</span><span><strong>${(water/1000).toFixed(2)}L</strong> water</span></div>${sessions.length?`<p class="small-muted">${sessions.map(s=>esc(s.name)).join(' · ')}</p>`:''}${check?`<p class="small-muted">${check.steps||'—'} steps · ${check.sleep||'—'}h sleep</p>`:''}${!meals.length&&!sessions.length&&!check&&!water?'<p class="small-muted">Nothing logged for this day yet.</p>':''}<button class="text-btn" onclick="selectedDate='${date}';go('food')">Open this day’s food diary →</button></div>`}
function folderIcon(){return '<svg width="20" height="18" viewBox="0 0 24 20" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M2 5V3a1 1 0 0 1 1-1h6l3 3h9a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1V5Z"/></svg>'}
function routineCard(r){return `<div class="routine-item"><div class="routine-item-heading"><h3>${esc(r.name)}</h3><button class="text-btn" onclick="routineModal('${r.id}')">Edit</button></div><p>${r.exercises.length} exercises · ${r.exercises.reduce((n,e)=>n+e.sets,0)} sets</p><button class="btn soft small" onclick="startWorkout('${r.id}')">Start Workout →</button></div>`}
function todayTrainingCard(){return `<div class="card"><div class="card-head"><h2>Your next session</h2><span class="tag">YOUR TRAINING</span></div><div class="workout-cover"><div><span class="tag">MAKE IT YOURS</span><h3>${state.active?'Keep your momentum':'Ready when you are.'}</h3><p>${state.active?'Your workout is in progress.':'Start fresh or choose a saved routine.'}</p></div></div><button class="btn full" onclick="startWorkout()">${state.active?'Continue workout':'Start Workout'} →</button><button class="text-btn full" onclick="go('workouts')">Browse your routines</button></div>`}
function toggleFolder(id){state.folderOpen[id]=!state.folderOpen[id];save();render()}
function chooseRoutineLocation(sessionId=null){modal(modalHead('Where should this routine go?')+`<p class="small-muted">Save it on its own, or keep related routines together.</p><div class="location-options"><button onclick="routineModal(null,null,${sessionId?"'"+sessionId+"'":'null'})"><strong>Without a folder</strong><small>A standalone routine in your library</small><span>→</span></button>${state.folders.map(f=>`<button onclick="routineModal(null,'${f.id}',${sessionId?"'"+sessionId+"'":'null'})"><strong>${esc(f.name)}</strong><small>Existing folder</small><span>→</span></button>`).join('')}<button onclick="folderModal(true,${sessionId?"'"+sessionId+"'":'null'})"><strong>＋ Create a new folder</strong><small>Name a folder, then create your routine</small><span>→</span></button></div>`)}
function folderModal(createRoutine=false,sessionId=null){modal(modalHead('Create a folder')+`<form id="folder-form"><label for="folder-name">Folder name</label><input id="folder-name" required maxlength="80" placeholder="e.g. Push / Pull / Legs" autofocus><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn">${createRoutine?'Create & continue':'Create folder'}</button></div></form>`);$('#folder-form').onsubmit=e=>{e.preventDefault();let name=$('#folder-name').value.trim();if(!name)return;let id=uid();state.folders.push({id,name});state.folderOpen[id]=true;save();closeModal();render();if(createRoutine)routineModal(null,id,sessionId);else toast('Folder created')}}
function customExerciseModal(){modal(modalHead('Add an exercise')+`<form onsubmit="addExercise(event)"><label for="exercise-name">Exercise name</label><input id="exercise-name" required maxlength="120" placeholder="e.g. Dumbbell bench press"><div class="form-grid"><div><label for="exercise-sets">Sets</label><input id="exercise-sets" type="number" required min="1" max="20" value="3"></div><div><label for="exercise-reps">Reps per set</label><input id="exercise-reps" type="number" required min="1" max="100" value="10"></div><div><label for="exercise-kg">Weight (kg)</label><input id="exercise-kg" type="number" required min="0" max="2000" step=".5" value="0"></div></div><div class="actions"><button class="btn secondary" type="button" onclick="closeModal()">Cancel</button><button class="btn">Add exercise</button></div></form>`)}
function addExercise(e){e.preventDefault();let name=$('#exercise-name').value.trim(),sets=Number($('#exercise-sets').value),reps=Number($('#exercise-reps').value),kg=Number($('#exercise-kg').value);if(!state.active||!name||!Number.isInteger(sets)||sets<1||sets>20||!Number.isInteger(reps)||reps<1||reps>100||!Number.isFinite(kg)||kg<0||kg>2000){toast('Check the exercise details');return}let group=state.active.sets.reduce((n,x)=>Math.max(n,x.group),-1)+1;state.active.rest=state.active.rest||{};state.active.rest[group]={duration:90,end:0};state.active.sets.push(...Array.from({length:sets},(_,i)=>({exercise:name,catalogId:catalogSelection?.id||null,catalogSource:catalogSelection?.source||null,group,set:i+1,reps,kg,done:false})));save();closeModal();render();toast('Exercise added')}
function offerSaveRoutine(id){modal(modalHead('Workout complete.')+`<p class="small-muted">Want to do this one again? Save the completed exercises as a reusable routine.</p><div class="actions"><button class="btn secondary" onclick="closeModal()">Done for now</button><button class="btn" onclick="chooseRoutineLocation('${id}')">Save as Routine</button></div>`)}

function restState(group){let a=state.active;if(!a)return null;a.rest=a.rest||{};return a.rest[group]||(a.rest[group]={duration:90,end:0})}
function formatRest(seconds){seconds=Math.max(0,Math.ceil(seconds));return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')}
function restRemaining(r){return r.end?Math.max(0,Math.ceil((r.end-Date.now())/1000)):r.duration}
function exerciseRestUI(group){let r=restState(group);return `<div class="exercise-rest"><div class="rest-heading"><label for="rest-${group}">REST TIMER <span id="rest-status-${group}">${r.end?'Running':'Ready'}</span></label><input id="rest-${group}" class="rest-input" aria-label="Rest time in minutes and seconds" type="text" inputmode="text" pattern="[0-9]{1,3}:[0-5][0-9]" value="${formatRest(restRemaining(r))}" onchange="editRest(${group},this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault();this.blur()}" title="Minutes:seconds, for example 2:30"></div><div class="rest-controls"><button class="btn secondary small" onclick="changeRest(${group},-15)">−15s</button><button class="btn secondary small" onclick="setRest(${group},60,true)">60s</button><button class="btn secondary small" onclick="setRest(${group},90,true)">90s</button><button class="btn secondary small" onclick="changeRest(${group},15)">+15s</button><button class="btn secondary small" onclick="resetRest(${group})">Reset</button><button class="btn small" onclick="runRest(${group})">Start</button></div><span class="rest-hint">Editable m:ss · Saved rest: <span id="rest-duration-${group}">${formatRest(r.duration)}</span></span></div>`}
function setRest(group,seconds,start=false){if(!Number.isFinite(seconds)||seconds<0||seconds>5999){toast('Use a rest time from 0:00 to 99:59');return}let r=restState(group);if(!r)return;r.duration=seconds;r.end=start&&seconds>0?Date.now()+seconds*1000:0;persistExerciseRest(group);refreshRest(group)}
function editRest(group,value){let m=/^(\d{1,2}):([0-5]\d)$/.exec(value.trim());if(!m){toast('Enter minutes:seconds, for example 2:30');refreshRest(group,true);return}let seconds=Number(m[1])*60+Number(m[2]),r=restState(group),running=!!r.end;setRest(group,seconds,running)}
function changeRest(group,delta){let r=restState(group);if(!r)return;let running=!!r.end;r.duration=Math.max(0,Math.min(5999,r.duration+delta));if(running){let remaining=Math.max(0,Math.min(5999,restRemaining(r)+delta));r.end=remaining?Date.now()+remaining*1000:0;if(!remaining)toast('Rest complete')}persistExerciseRest(group);refreshRest(group)}
function resetRest(group){let r=restState(group);if(!r)return;r.end=0;save();refreshRest(group)}
function runRest(group){let r=restState(group);if(!r||!r.duration){toast('Set a rest time first');return}r.end=Date.now()+r.duration*1000;save();refreshRest(group)}
function persistExerciseRest(group){let a=state.active,r=restState(group),name=a.sets.find(s=>s.group===group)?.exercise;if(!a.unplanned){let routine=state.routines.find(x=>x.id===a.routineId);let ex=routine?.exercises.find(x=>x.name===name);if(ex)ex.rest=r.duration}save()}
function refreshRest(group,force=false){let r=restState(group);if(!r)return;let input=$('#rest-'+group);if(input&&(force||document.activeElement!==input))input.value=formatRest(restRemaining(r));let status=$('#rest-status-'+group);if(status)status.textContent=r.end?'Running':'Ready';let duration=$('#rest-duration-'+group);if(duration)duration.textContent=formatRest(r.duration)}
setInterval(()=>{if(window.frameElement||!state.active)return;Object.entries(state.active.rest||{}).forEach(([group,r])=>{if(r.end&&r.end<=Date.now()){r.end=0;save();let name=state.active.sets.find(s=>s.group===Number(group))?.exercise||'Exercise';toast(name+' · Rest complete');let input=$('#rest-'+group);if(input&&document.activeElement!==input)input.value='0:00';let status=$('#rest-status-'+group);if(status)status.textContent='Complete';}else if(page==='workouts')refreshRest(group)})},500);
function progressPage(){return bodyProgressPage()}

function workoutPage(){return baseWorkoutPage()}

function settingsPage(){return baseSettingsPage()}
